// Created: 2026-09-18

/**
 * The Jev routing seam for /ork:auto, behind a flag that defaults to off.
 *
 * One TypeSafe System One request per build-shaped prompt: a Choice over the
 * nineteen route classes plus four side judgments (worktree, browser,
 * mutation risk, operator). The caller (prompt/executor-route-nudge) decides
 * what to inject; this module owns the request, the redactor, the egress
 * guard, the balance guard, the transport and the record.
 *
 * Modes (ORK_ROUTE_JEV): unset or `off` means no call at all; `shadow` calls
 * and records, injects nothing; `steer` calls, records, and at or above the
 * floor the nudge names the executor. Same vocabulary as
 * ORK_SESSION_CATEGORY_PROVIDER and ORK_EXPECT_JEV.
 *
 * Fail open on routing (no key, timeout, non-2xx, malformed body, confidence
 * below the floor, budget exceeded: `decided_by=table`, nothing changes) and
 * fail closed on egress (a secret, email, phone, id or client name that
 * survives redaction refuses the call: `decided_by=egress`). Nothing here
 * throws to the caller and nothing here blocks a prompt.
 *
 * Egress posture is the expect lane's, not the session category lane's: every
 * outbound string is JSON escape decoded, redacted and truncated, and the
 * serialized request is scanned again in raw and decoded form before it
 * leaves. No prompt text is ever written to disk; the record carries a sha256
 * of the redacted text.
 *
 * @see https://github.com/yonatangross/orchestkit/issues/4233
 */

import { spawnSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import {
  appendFileSync,
  existsSync,
  mkdirSync,
  readdirSync,
  readFileSync,
  writeFileSync,
} from 'node:fs';
import { basename, join } from 'node:path';
import defaults from './route-judgment.defaults.json';
import { getSessionStorageDir } from './paths.js';
import {
  ROUTE_CLASS_TO_EXECUTOR,
  ROUTE_QUESTIONS,
  parseRouteIntent,
  type RouteIntent,
  type RouteTarget,
} from './route-classes.js';

