/** Per-session dir, the same one session-identity.jev.json lives in. */
export function routeSessionDir(sessionId: string, projectDir: string, env: NodeJS.ProcessEnv = process.env): string {
  if (env.CLAUDE_PLUGIN_DATA) return join(getSessionStorageDir(), sessionId);
  return join(projectDir, '.claude', 'memory', 'sessions', sessionId);
}

/** Plugin-wide dir for the daily budget and the trip marker. */
export function routeDataDir(projectDir: string, env: NodeJS.ProcessEnv = process.env): string {
  if (env.CLAUDE_PLUGIN_DATA) return join(env.CLAUDE_PLUGIN_DATA, 'jev-route');
  return join(projectDir, '.claude', 'memory', 'jev-route');
}

export const FILE_ROUTE_RECORDS = 'jev-route.jsonl';
export const FILE_ROUTE_BUDGET = 'jev-route-budget.json';
export const FILE_ROUTE_TRIPPED = 'jev-route-tripped.json';

// ---------------------------------------------------------------------------
// Redactor (ported from src/skills/expect/scripts/jev_shadow.py, extended)
// ---------------------------------------------------------------------------

const JSON_ESCAPE_RE = /\\(?:u[0-9a-fA-F]{4}|["\\/bfnrt])/g;

/**
 * Decode JSON-style escapes carried verbatim in input, so a value smuggled as
 * `token=<value>` is caught the same as `token=<value>`.
 */
export function unescapeJson(text: string): string {
  return text.replace(JSON_ESCAPE_RE, (m) => {
    try {
      return JSON.parse(`"${m}"`) as string;
    } catch {
      return m;
    }
  });
}

export const SECRET_PATTERNS: RegExp[] = [
  /bearer\s+[A-Za-z0-9._~+/=-]{6,}/gi,
  /\b(?:token|secret|passwd|password|api[-_]?key|apikey|session|cookie|credential|auth)s?\s*[:=]\s*[^\s;,]{4,}/gi,
  /eyJ[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{4,}/g,
  /\b(?:ghp|gho|ghu|ghs|ghr)_[A-Za-z0-9_]{16,}/g,
  /\bgithub_pat_[A-Za-z0-9_]{20,}/g,
  /\bsk-[A-Za-z0-9_-]{12,}/g,
  /\bxox[baprs]-[A-Za-z0-9-]{8,}/g,
  /\bAKIA[0-9A-Z]{16}\b/g,
  /\bapik[A-Za-z0-9_-]{20,}/g,
  /\bops_[A-Za-z0-9]{20,}/g,
  /op:\/\/[^\s"'`)\]]+/g,
  /\b[A-Fa-f0-9]{40,}\b/g,
];
/** Addresses, and the dotless `user@host` shape a pasted shell prompt carries. */
export const EMAIL_PATTERN = /[\w.+-]+@[\w-]+(?:\.[\w.-]+)?/g;
/** Israeli mobiles: 05x with or without separators, and the +972 5x form. */
export const PHONE_PATTERN = /(?<!\d)(?:\+?972[-\s]?|0)5\d[-\s]?\d{3}[-\s]?\d{4}(?!\d)/g;
/** Nine digit runs: Israeli id numbers. Runs after phones, which are longer. */
export const NINE_DIGIT_PATTERN = /(?<!\d)\d{9}(?!\d)/g;

/** Segments too generic to stand alone as a client reference (hq-ext prompt-context-injector). */
const CLIENT_SEGMENT_STOPLIST = new Set([
  'test', 'demo', 'temp', 'draft', 'internal', 'template', 'strategy', 'coaching', 'protocol',
  'client', 'clients', 'main', 'core', 'data', 'docs', 'site', 'misc', 'shared', 'common',
]);
const MIN_SEGMENT_LEN = 4;

function escapeRegExp(s: string): string {
  return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

/**
 * Tokens a client directory name yields: the slug, its spaced form, and each
 * segment of four characters or more that is not on the stoplist. Same
 * segment logic as hq-ext's clientMatchers.
 */
export function clientTokensFromNames(names: string[]): string[] {
  const tokens = new Set<string>();
  for (const name of names) {
    if (!name || name.startsWith('_') || name.startsWith('.')) continue;
    const spaced = name.replace(/[-_]+/g, ' ');
    tokens.add(name);
    tokens.add(spaced);
    for (const seg of spaced.split(' ')) {
      if (seg.length >= MIN_SEGMENT_LEN && !CLIENT_SEGMENT_STOPLIST.has(seg.toLowerCase())) tokens.add(seg);
    }
  }
  return [...tokens].filter(Boolean).sort((a, b) => b.length - a.length);
}

/** Read `<projectDir>/clients/`. A project without one is the common case, not an error. */
export function readClientDirNames(projectDir: string): string[] {
  try {
    return readdirSync(join(projectDir, 'clients'), { withFileTypes: true })
      .filter((e) => e.isDirectory())
      .map((e) => e.name);
  } catch {
    return [];
  }
}

export function buildClientPattern(tokens: string[]): RegExp | null {
  if (tokens.length === 0) return null;
  return new RegExp(`\\b(?:${tokens.map(escapeRegExp).join('|')})\\b`, 'gi');
}

export interface Redaction {
  text: string;
  /** Number of replacements made, all patterns together. */
  count: number;
}

/**
 * Decode JSON escapes, replace every secret, email, phone, nine digit id and
 * client token, collapse whitespace, truncate. Order matters: secrets before
 * emails (an op:// ref has no `@`), emails before phones (an address can
 * carry digits), phones before nine digit ids (a mobile contains one).
 */
export function redactPrompt(text: string, maxChars: number, clientPattern: RegExp | null): Redaction {
  let count = 0;
  const swap = (input: string, re: RegExp, token: string): string =>
    input.replace(re, () => {
      count += 1;
      return token;
    });
  let out = unescapeJson(typeof text === 'string' ? text : '');
  for (const re of SECRET_PATTERNS) out = swap(out, re, '[SECRET]');
  out = swap(out, EMAIL_PATTERN, '[EMAIL]');
  out = swap(out, PHONE_PATTERN, '[PHONE]');
  out = swap(out, NINE_DIGIT_PATTERN, '[SECRET]');
  if (clientPattern) out = swap(out, clientPattern, '[CLIENT]');
  out = out.replace(/\s+/g, ' ').trim();
  return { text: out.slice(0, maxChars), count };
}

// ---------------------------------------------------------------------------
// Egress guard
// ---------------------------------------------------------------------------

/** What may never leave, checked after redaction on the serialized request. */
const EGRESS_GUARD: Array<{ name: string; re: RegExp }> = [
  { name: 'email', re: /[\w.+-]+@[\w-]+(?:\.[\w.-]+)?/ },
  { name: 'phone', re: /(?<!\d)(?:\+?972[-\s]?|0)5\d[-\s]?\d{3}[-\s]?\d{4}(?!\d)/ },
  {
    name: 'secret',
    re: /(op:\/\/|\bsk-[A-Za-z0-9_-]{12,}|\bghp_[A-Za-z0-9]{20,}|\bgithub_pat_[A-Za-z0-9_]{20,}|\bapik[A-Za-z0-9_-]{20,}|\bops_[A-Za-z0-9]{20,}|\bxox[baprs]-[A-Za-z0-9-]{8,}|\bAKIA[0-9A-Z]{16}\b|eyJ[A-Za-z0-9_-]{20,}\.)/,
  },
  { name: 'id', re: /(?<!\d)\d{9}(?!\d)/ },
];

/**
 * Scan the serialized request in both its raw and JSON escape decoded forms.
 * The client pattern is applied to the `state` object only: the question text
 * is a fixed constant, and a client directory that happens to share a word
 * with it would otherwise refuse every call on that machine.
 */
export function egressScan(request: RouteRequest, clientPattern: RegExp | null): string | null {
  // Serialized, decoded once (what the wire carries as text), decoded twice
  // (an escape sequence smuggled inside the prompt text itself).
  const forms = (text: string): string[] => {
    const once = unescapeJson(text);
    return [text, once, unescapeJson(once)];
  };
  for (const candidate of forms(JSON.stringify(request))) {
    for (const guard of EGRESS_GUARD) if (guard.re.test(candidate)) return guard.name;
  }
  if (clientPattern) {
    for (const candidate of forms(JSON.stringify(request.state))) {
      clientPattern.lastIndex = 0;
      if (clientPattern.test(candidate)) {
        clientPattern.lastIndex = 0;
        return 'client';
      }
    }
  }
  return null;
}

// ---------------------------------------------------------------------------
// Request
// ---------------------------------------------------------------------------

export interface RouteRequest {
  state: { prompt: string; opening_turn: boolean; repo: string };
  model: string;
  questions: typeof ROUTE_QUESTIONS;
}

export function sha256(text: string): string {
  return createHash('sha256').update(text, 'utf8').digest('hex');
}

export interface BuiltRequest {
  request: RouteRequest;
  redacted: number;
  inputSha256: string;
}

export function buildRouteRequest(
  prompt: string,
  opts: { openingTurn: boolean; repo: string; config: RouteConfig; clientPattern: RegExp | null },
): BuiltRequest {
  const red = redactPrompt(prompt, opts.config.maxPromptChars, opts.clientPattern);
  const repo = redactPrompt(opts.repo, opts.config.maxRepoChars, opts.clientPattern).text;
  return {
    request: {
      state: { prompt: red.text, opening_turn: opts.openingTurn, repo },
      model: opts.config.model,
      questions: ROUTE_QUESTIONS,
    },
    redacted: red.count,
    inputSha256: sha256(red.text),
  };
}

// ---------------------------------------------------------------------------
// Answer
// ---------------------------------------------------------------------------

export interface RouteAnswer {
  intent: RouteIntent;
  confidence: number | null;
  probabilities: Partial<Record<RouteIntent, number>>;
  worktree: number | null;
  browser: number | null;
  mutation: number | null;
  operator: number | null;
  inputTokens: number | null;
}

function num(v: unknown): number | null {
  if (typeof v === 'number' && Number.isFinite(v)) return v;
  if (typeof v === 'string' && v.trim() !== '' && Number.isFinite(Number(v))) return Number(v);
  return null;
}

/** A routing gate accepts only a JSON number in the closed probability range. */
function probability(v: unknown): number | null {
  return typeof v === 'number' && Number.isFinite(v) && v >= 0 && v <= 1 ? v : null;
}

function noul(answer: unknown): number | null {
  if (typeof answer !== 'object' || answer === null) return null;
  const a = answer as Record<string, unknown>;
  const direct = num(a.noul);
  if (direct !== null) return direct;
  if (typeof a.probabilities === 'object' && a.probabilities !== null) {
    return num((a.probabilities as Record<string, unknown>).true);
  }
  return null;
}

/** Parse a response body. Null unless the intent choice is a member of the closed set. */
export function parseRouteAnswer(body: unknown): RouteAnswer | null {
  if (typeof body !== 'object' || body === null) return null;
  const answers = (body as Record<string, unknown>).answers;
  if (typeof answers !== 'object' || answers === null) return null;
  const all = answers as Record<string, unknown>;
  const intentAnswer = all.intent;
  if (typeof intentAnswer !== 'object' || intentAnswer === null) return null;
  const ia = intentAnswer as Record<string, unknown>;
  const intent = parseRouteIntent(ia.choice);
  if (!intent) return null;
  const probabilities: Partial<Record<RouteIntent, number>> = {};
  if (typeof ia.probabilities === 'object' && ia.probabilities !== null) {
    for (const [k, v] of Object.entries(ia.probabilities as Record<string, unknown>)) {
      const key = parseRouteIntent(k);
      const p = num(v);
      if (key && p !== null) probabilities[key] = p;
    }
  }
  const mutationAnswer = all.mutation_risk;
  let mutation: number | null = null;
  if (typeof mutationAnswer === 'object' && mutationAnswer !== null) {
    const ma = mutationAnswer as Record<string, unknown>;
    mutation = num(ma.score) ?? num(ma.value);
  }
  const usage = (body as Record<string, unknown>).usage;
  const tokens =
    typeof usage === 'object' && usage !== null ? num((usage as Record<string, unknown>).input_tokens) : null;
  return {
    intent,
    confidence: probability(ia.confidence),
    probabilities,
    worktree: noul(all.needs_worktree),
    browser: noul(all.needs_browser),
    mutation,
    operator: noul(all.needs_operator),
    inputTokens: tokens,
  };
}

// ---------------------------------------------------------------------------
// Balance guard: daily token budget and the 402/429 trip
// ---------------------------------------------------------------------------

function utcDay(now: number): string {
  return new Date(now).toISOString().slice(0, 10);
}

function readJson(path: string): Record<string, unknown> | null {
  try {
    if (!existsSync(path)) return null;
    const raw = JSON.parse(readFileSync(path, 'utf8'));
    return typeof raw === 'object' && raw !== null ? (raw as Record<string, unknown>) : null;
  } catch {
    return null;
  }
}

/** Tokens spent so far in the current UTC day, per the budget file. */
export function readBudgetTokens(dataDir: string, now: number): number {
  const raw = readJson(join(dataDir, FILE_ROUTE_BUDGET));
  if (!raw || raw.day !== utcDay(now)) return 0;
  return num(raw.tokens) ?? 0;
}

export function addBudgetTokens(dataDir: string, tokens: number, now: number): void {
  try {
    mkdirSync(dataDir, { recursive: true });
    const spent = readBudgetTokens(dataDir, now) + Math.max(0, tokens);
    writeFileSync(join(dataDir, FILE_ROUTE_BUDGET), JSON.stringify({ day: utcDay(now), tokens: spent }), {
      encoding: 'utf8',
      mode: 0o600,
    });
  } catch {
    /* an unwritable data dir only loses the count */
  }
}

/** True while a 402 or 429 trip is younger than `tripHours`. */
export function isTripped(dataDir: string, now: number, tripHours: number): boolean {
  const raw = readJson(join(dataDir, FILE_ROUTE_TRIPPED));
  if (!raw || typeof raw.ts !== 'string') return false;
  const at = Date.parse(raw.ts);
  if (!Number.isFinite(at)) return false;
  return now - at < tripHours * 3_600_000;
}

export function writeTrip(dataDir: string, now: number, status: number): void {
  try {
    mkdirSync(dataDir, { recursive: true });
    writeFileSync(join(dataDir, FILE_ROUTE_TRIPPED), JSON.stringify({ ts: new Date(now).toISOString(), status }), {
      encoding: 'utf8',
      mode: 0o600,
    });
  } catch {
    /* fail open */
  }
}

// ---------------------------------------------------------------------------
// Transport: one async fetch, or one synchronous child node process
// ---------------------------------------------------------------------------

export type TransportResult =
  | { ok: true; status: number; body: unknown; latencyMs: number }
  | { ok: false; error: string; status: number | null; latencyMs: number };

/** Ask once. Never throws; every failure is an `ok: false` result. */
export async function postRouteRequest(
  request: RouteRequest,
  apiKey: string,
  config: RouteConfig,
  fetchImpl: typeof fetch = fetch,
  now: () => number = Date.now,
): Promise<TransportResult> {
  const started = now();
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), config.timeoutMs);
  try {
    const res = await fetchImpl(config.endpoint, {
      method: 'POST',
      headers: { Authorization: `Bearer ${apiKey}`, 'Content-Type': 'application/json' },
      body: JSON.stringify(request),
      signal: controller.signal,
    });
    const latencyMs = now() - started;
    if (!res.ok) return { ok: false, error: `http ${res.status}`, status: res.status, latencyMs };
    try {
      return { ok: true, status: res.status, body: await res.json(), latencyMs };
    } catch {
      return { ok: false, error: 'malformed body', status: res.status, latencyMs: now() - started };
    }
  } catch (error) {
    return {
      ok: false,
      // Error name only, never the request: the request carries the key header.
      error: controller.signal.aborted ? 'timeout' : error instanceof Error ? error.name : 'fetch failed',
      status: null,
      latencyMs: now() - started,
    };
  } finally {
    clearTimeout(timer);
  }
}

/**
 * The child that performs the synchronous call for `steer`. The dispatcher is
 * synchronous, so a steered nudge needs the answer before it returns; a child
 * node process is the one dependency-free way to block on a fetch. The body
 * arrives on stdin, the key and endpoint in the child's environment (never on
 * argv, which is visible to every process), and the reply is one JSON line.
 */
export const ROUTE_CHILD_SCRIPT = [
  'const key = process.env.ORK_TYPESAFE_API_KEY || "";',
  'const endpoint = process.env.ORK_ROUTE_JEV_ENDPOINT || "";',
  'const timeout = Number(process.env.ORK_ROUTE_JEV_TIMEOUT_MS || "3000");',
  'let body = "";',
  'process.stdin.setEncoding("utf8");',
  'process.stdin.on("data", (d) => { body += d; });',
  'process.stdin.on("end", async () => {',
  '  const c = new AbortController();',
  '  const t = setTimeout(() => c.abort(), timeout);',
  '  const started = Date.now();',
  '  try {',
  '    const res = await fetch(endpoint, { method: "POST", headers: { Authorization: "Bearer " + key, "Content-Type": "application/json" }, body, signal: c.signal });',
  '    const text = await res.text();',
  '    process.stdout.write(JSON.stringify({ status: res.status, text, latencyMs: Date.now() - started }));',
  '  } catch (e) {',
  '    process.stdout.write(JSON.stringify({ error: c.signal.aborted ? "timeout" : (e && e.name) || "fetch failed", latencyMs: Date.now() - started }));',
  '  } finally { clearTimeout(t); }',
  '});',
].join('\n');

export type SpawnLike = (
  cmd: string,
  args: string[],
  opts: { input: string; env: NodeJS.ProcessEnv; timeout: number; encoding: 'utf8' },
) => {
  status: number | null;
  stdout: string;
  error?: Error;
};

export function postRouteRequestSync(
  request: RouteRequest,
  apiKey: string,
  config: RouteConfig,
  spawnImpl: SpawnLike = spawnSync as unknown as SpawnLike,
  now: () => number = Date.now,
): TransportResult {
  const started = now();
  let child: ReturnType<SpawnLike>;
  try {
    child = spawnImpl(process.execPath, ['-e', ROUTE_CHILD_SCRIPT], {
      input: JSON.stringify(request),
      env: {
        PATH: process.env.PATH || '',
        [TYPESAFE_KEY_ENV]: apiKey,
        [ROUTE_ENDPOINT_ENV]: config.endpoint,
        [ROUTE_TIMEOUT_ENV]: String(config.timeoutMs),
      },
      timeout: config.timeoutMs + 1_000,
      encoding: 'utf8',
    });
  } catch {
    return { ok: false, error: 'spawn failed', status: null, latencyMs: now() - started };
  }
  const latencyMs = now() - started;
  if (child.error || child.status !== 0 || !child.stdout) {
    return { ok: false, error: child.error ? 'spawn failed' : 'child failed', status: null, latencyMs };
  }
  let reply: Record<string, unknown>;
  try {
    reply = JSON.parse(child.stdout) as Record<string, unknown>;
  } catch {
    return { ok: false, error: 'malformed child reply', status: null, latencyMs };
  }
  if (!reply || typeof reply !== 'object' || Array.isArray(reply)) {
    return { ok: false, error: 'malformed child reply', status: null, latencyMs };
  }
  if (typeof reply.error === 'string') return { ok: false, error: reply.error, status: null, latencyMs };
  const status = num(reply.status) ?? 0;
  if (status < 200 || status >= 300) return { ok: false, error: `http ${status}`, status, latencyMs };
  try {
    return { ok: true, status, body: JSON.parse(String(reply.text)), latencyMs };
  } catch {
    return { ok: false, error: 'malformed body', status, latencyMs };
  }
}

// ---------------------------------------------------------------------------
// The seam: prepare, settle, record
// ---------------------------------------------------------------------------

export type DecidedBy = 'jev' | 'table' | 'off' | 'budget' | 'egress';

export interface RouteVerdict {
  /** Actual observed incumbent pick, never inferred from decided_by. */
  incumbent_intent?: RouteIntent | null;
  decided_by: DecidedBy;
  intent: RouteIntent | null;
  conf: number | null;
  top3: Array<[RouteIntent, number]>;
  worktree: number | null;
  browser: number | null;
  mutation: number | null;
  operator: number | null;
  floor: number;
  latency_ms: number;
  input_tokens: number | null;
  redacted: number;
  flag: RouteMode;
  input_sha256: string | null;
  /** The executor the top class maps to, or null when the class has none. */
  target: RouteTarget | null;
  error: string | null;
}

export interface RouteJudgmentOptions {
  /** Supply only an independently observed incumbent classification. */
  incumbentIntent?: RouteIntent;
  prompt: string;
  sessionId: string;
  projectDir: string;
  env?: NodeJS.ProcessEnv;
  /** Client directory names to redact; defaults to `<projectDir>/clients/`. */
  clientNames?: string[];
  /** Skip the jsonl record (the eval replay keeps its own). */
  record?: boolean;
  now?: () => number;
  log?: (message: string, level: 'info' | 'warn') => void;
  fetchImpl?: typeof fetch;
  spawnImpl?: SpawnLike;
}

interface Prepared {
  incumbentIntent: RouteIntent | null;
  config: RouteConfig;
  env: NodeJS.ProcessEnv;
  apiKey: string;
  built: BuiltRequest;
  sessionDir: string;
  dataDir: string;
  now: () => number;
  log: (message: string, level: 'info' | 'warn') => void;
  record: boolean;
}

function baseVerdict(config: RouteConfig, decidedBy: DecidedBy, extra: Partial<RouteVerdict> = {}): RouteVerdict {
  return {
    decided_by: decidedBy,
    intent: null,
    conf: null,
    top3: [],
    worktree: null,
    browser: null,
    mutation: null,
    operator: null,
    floor: config.floor,
    latency_ms: 0,
    input_tokens: null,
    redacted: 0,
    flag: config.mode,
    input_sha256: null,
    target: null,
    error: null,
    ...extra,
  };
}

/** Gates, redaction and the egress scan. Either an early verdict or a request ready to send. */
function prepare(opts: RouteJudgmentOptions): { verdict: RouteVerdict } | { prepared: Prepared } {
  const env = opts.env ?? process.env;
  const config = resolveRouteConfig(env);
  const now = opts.now ?? Date.now;
  const log = opts.log ?? (() => {});
  const record = opts.record ?? true;
  const sessionDir = routeSessionDir(opts.sessionId, opts.projectDir, env);
  const dataDir = routeDataDir(opts.projectDir, env);
  const at = now();

  const early = (decidedBy: DecidedBy, error: string): { verdict: RouteVerdict } => {
    const verdict = baseVerdict(config, decidedBy, { error, incumbent_intent: opts.incumbentIntent ?? null });
    if (record) appendRouteRecord(sessionDir, verdict, at);
    return { verdict };
  };
  if (config.mode === 'off') return { verdict: baseVerdict(config, 'off') };
  const apiKey = resolveTypesafeKey(env);
  if (!apiKey) return early('table', 'no key');
  if (isTripped(dataDir, at, config.tripHours)) {
    return early('budget', 'tripped');
  }
  if (readBudgetTokens(dataDir, at) >= config.dailyTokens) {
    return early('budget', 'daily tokens');
  }

  const clientNames = opts.clientNames ?? readClientDirNames(opts.projectDir);
  const clientPattern = buildClientPattern(clientTokensFromNames(clientNames));
  const built = buildRouteRequest(opts.prompt, {
    openingTurn: !existsSync(sessionDir),
    repo: basename(opts.projectDir || ''),
    config,
    clientPattern,
  });
  const leak = egressScan(built.request, clientPattern);
  if (leak) {
    const verdict = baseVerdict(config, 'egress', {
      error: `egress ${leak}`,
      redacted: built.redacted,
      input_sha256: built.inputSha256,
    });
    if (record) appendRouteRecord(sessionDir, verdict, at);
    return { verdict };
  }
  return { prepared: { incumbentIntent: opts.incumbentIntent ?? null, config, env, apiKey, built, sessionDir, dataDir, now, log, record } };
}

/** Parse, floor, budget, record. */
function settle(p: Prepared, result: TransportResult): RouteVerdict {
  const at = p.now();
  const common: Partial<RouteVerdict> = {
    incumbent_intent: p.incumbentIntent,
    latency_ms: Math.round(result.latencyMs),
    redacted: p.built.redacted,
    input_sha256: p.built.inputSha256,
  };
  let verdict: RouteVerdict;
  if (!result.ok) {
    if (result.status === 402 || result.status === 429) {
      writeTrip(p.dataDir, at, result.status);
      p.log(`route jev: http ${result.status}, seam off for ${p.config.tripHours} h`, 'warn');
    }
    verdict = baseVerdict(p.config, 'table', { ...common, error: result.error });
  } else {
    const answer = parseRouteAnswer(result.body);
    if (!answer) {
      verdict = baseVerdict(p.config, 'table', { ...common, error: 'malformed answer' });
    } else {
      if (answer.inputTokens !== null) addBudgetTokens(p.dataDir, answer.inputTokens, at);
      const top3 = (Object.entries(answer.probabilities) as Array<[RouteIntent, number]>)
        .sort((a, b) => b[1] - a[1])
        .slice(0, 3);
      const aboveFloor = answer.confidence !== null && answer.confidence >= p.config.floor;
      verdict = baseVerdict(p.config, p.config.mode === 'steer' && aboveFloor ? 'jev' : 'table', {
        ...common,
        intent: answer.intent,
        conf: answer.confidence,
        top3,
        worktree: answer.worktree,
        browser: answer.browser,
        mutation: answer.mutation,
        operator: answer.operator,
        input_tokens: answer.inputTokens,
        target: ROUTE_CLASS_TO_EXECUTOR[answer.intent],
      });
    }
  }
  if (p.record) appendRouteRecord(p.sessionDir, verdict, at);
  return verdict;
}

/** The seam, asynchronous (shadow mode). Never throws. */
export async function routeJudgment(opts: RouteJudgmentOptions): Promise<RouteVerdict> {
  const step = prepare(opts);
  if ('verdict' in step) return step.verdict;
  const p = step.prepared;
  const result = await postRouteRequest(p.built.request, p.apiKey, p.config, opts.fetchImpl, p.now);
  return settle(p, result);
}

/** The seam, synchronous (steer mode). Never throws. */
export function routeJudgmentSync(opts: RouteJudgmentOptions): RouteVerdict {
  const step = prepare(opts);
  if ('verdict' in step) return step.verdict;
  const p = step.prepared;
  const result = postRouteRequestSync(p.built.request, p.apiKey, p.config, opts.spawnImpl, p.now);
  return settle(p, result);
}

// ---------------------------------------------------------------------------
// Record and log line
// ---------------------------------------------------------------------------

export interface RouteRecord {
  seam: 'route';
  incumbent_intent: RouteIntent | null;
  agree: boolean | null;
  below_floor: boolean | null;
  high_confidence_disagreement: boolean | null;
  error: string | null;
  ts: string;
  input_sha256: string | null;
  intent: RouteIntent | null;
  conf: number | null;
  top3: Array<[RouteIntent, number]>;
  worktree: number | null;
  browser: number | null;
  mutation: number | null;
  operator: number | null;
  floor: number;
  decided_by: DecidedBy;
  latency_ms: number;
  input_tokens: number | null;
  redacted: number;
  flag: RouteMode;
}

export function toRouteRecord(v: RouteVerdict, now: number): RouteRecord {
  const incumbent = v.incumbent_intent ?? null;
  const agree = incumbent && v.intent ? incumbent === v.intent : null;
  const belowFloor = v.conf === null ? null : v.conf < v.floor;
  return {
    seam: 'route',
    incumbent_intent: incumbent,
    agree,
    below_floor: belowFloor,
    high_confidence_disagreement: agree === null || belowFloor === null ? null : !agree && !belowFloor,
    error: v.error,
    ts: new Date(now).toISOString(),
    input_sha256: v.input_sha256,
    intent: v.intent,
    conf: v.conf,
    top3: v.top3,
    worktree: v.worktree,
    browser: v.browser,
    mutation: v.mutation,
    operator: v.operator,
    floor: v.floor,
    decided_by: v.decided_by,
    latency_ms: v.latency_ms,
    input_tokens: v.input_tokens,
    redacted: v.redacted,
    flag: v.flag,
  };
}

/** Append one record, mode 0600, no prompt text. An unwritable dir only loses the sample. */
export function appendRouteRecord(sessionDir: string, verdict: RouteVerdict, now: number): void {
  try {
    mkdirSync(sessionDir, { recursive: true });
    appendFileSync(join(sessionDir, FILE_ROUTE_RECORDS), `${JSON.stringify(toRouteRecord(verdict, now))}\n`, {
      encoding: 'utf8',
      mode: 0o600,
    });
  } catch {
    /* fail open */
  }
}

const f2 = (n: number | null): string => (n === null ? 'na' : n.toFixed(2));

/** The one hook log line, same shape in both plugins. */
export function formatRouteLogLine(v: RouteVerdict): string {
  const top3 = v.top3.map(([k, p]) => `${k}:${p.toFixed(2)}`).join(',');
  return (
    `route jev: intent=${v.intent ?? 'none'} conf=${f2(v.conf)} top3=${top3 || 'none'} ` +
    `worktree=${f2(v.worktree)} browser=${f2(v.browser)} mutation=${v.mutation === null ? 'na' : v.mutation.toFixed(1)} ` +
    `operator=${f2(v.operator)} floor=${f2(v.floor)} decided_by=${v.decided_by} ` +
    `latency_ms=${v.latency_ms} input_tokens=${v.input_tokens ?? 0} redacted=${v.redacted}`
  );
}
